////////////////////////////////////////////////////////////
//                  IMAGE SHADER
////////////////////////////////////////////////////////////
#define MAX_SITES 200

// same N as in Buffer A
#define N 32
#define TOTAL_WIRE_POINTS (2*N)

#define MAX_STEPS 100
#define MAX_DIST 50.0
#define CUBE_SIZE 1.0
#define MAX_SITES_PER_CELL 50

const vec3 CUBE_SIZE_VEC     = vec3(CUBE_SIZE);
const vec3 NEG_CUBE_SIZE_VEC = vec3(-CUBE_SIZE);

struct Site {
    vec3 pos;
    float weight;
};

// --------------------------------------------------
Site get_sites(int idx)
{
    vec4 data = texelFetch(iChannel0, ivec2(idx,0),0);
    Site s;
    s.pos    = data.rgb;
    s.weight = data.a;
    return s;
}

int get_grid_count(int idx)
{
    return int(texelFetch(iChannel0, ivec2(0,idx+1),0).r);
}

int get_grid_sites(int idx, int jdx)
{
    return int(texelFetch(iChannel0, ivec2(jdx+1,idx+1),0).r);
}

ivec3 posToGrid(vec3 pos)
{
    return clamp(
        ivec3((pos / CUBE_SIZE + 1.0)*0.5*5.0),
        ivec3(0), ivec3(4)
    );
}

int gridIndex(ivec3 c)
{
    return c.x + 5*(c.y + 5*c.z);
}

// --------------------------------------------------
void getCellInfo(
    vec3 p,
    out float d1, out int cellId,
    out float d2, out float d3
){
    d1 = MAX_DIST;
    d2 = MAX_DIST;
    d3 = MAX_DIST;
    cellId = -1;

    ivec3 gp = posToGrid(p);
    int cIdx = gridIndex(gp);
    int cCount= get_grid_count(cIdx);

    for(int i=0;i<cCount;i++){
        int sId = get_grid_sites(cIdx,i);
        float dist= length(p - get_sites(sId).pos);
        if(dist<d1){
            d3=d2; d2=d1; d1=dist; cellId=sId;
        }
        else if(dist<d2){
            d3=d2; d2=dist;
        }
        else if(dist<d3){
            d3=dist;
        }
    }

    // Also check immediate neighbors in the 5x5x5 grid
    for(int dx=-1; dx<=1; dx++){
        for(int dy=-1; dy<=1; dy++){
            for(int dz=-1; dz<=1; dz++){
                if(dx==0 && dy==0 && dz==0) continue;
                ivec3 nb=gp+ivec3(dx,dy,dz);
                if(any(lessThan(nb,ivec3(0)))||any(greaterThanEqual(nb,ivec3(5)))) continue;
                int nbIdx= gridIndex(nb);
                int nCount= get_grid_count(nbIdx);
                for(int k=0;k<nCount;k++){
                    int sId = get_grid_sites(nbIdx,k);
                    float dist=length(p - get_sites(sId).pos);

                    if(dist<d1){
                        d3=d2; d2=d1; d1=dist; cellId=sId;
                    }
                    else if(dist<d2){
                        d3=d2; d2=dist;
                    }
                    else if(dist<d3){
                        d3=dist;
                    }
                }
            }
        }
    }
}

// --------------------------------------------------
vec2 cubeIntersection(vec3 ro, vec3 rd)
{
    vec3 invDir=1.0/rd;
    vec3 t1=(NEG_CUBE_SIZE_VEC - ro)*invDir;
    vec3 t2=(CUBE_SIZE_VEC - ro)*invDir;
    vec3 tn=min(t1,t2);
    vec3 tf=max(t1,t2);

    float nearT=max(max(tn.x,tn.y),tn.z);
    float farT= min(min(tf.x,tf.y),tf.z);

    return vec2(nearT,farT);
}

// --------------------------------------------------
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    // normalized pixel coords
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Default “free-flight” camera from mouse
    float yaw   = (iMouse.x / iResolution.x) * 6.283185;
    float pitch = (iMouse.y / iResolution.y) * 3.14159265 - 1.5707963;
    float radius = 2.5;

    // ------------------------------------------------------
    // *** If mouse hasn’t moved (i.e., iMouse.xy == 0),
    //     animate the camera automatically:
    // ------------------------------------------------------
    // We'll do a simple orbit around the origin.
    if (dot(iMouse.xy, iMouse.xy) < 1e-6)  // i.e. near zero
    {
        yaw    = iTime * 0.2;
        pitch  = 0.2 * sin(iTime * 0.1);
        radius = 2.3 + 0.2 * sin(iTime * 0.3);
    }

    // Camera position
    vec3 ro = vec3(
        radius * cos(pitch) * sin(yaw),
        radius * sin(pitch),
        radius * cos(pitch) * cos(yaw)
    );

    // Look toward origin
    vec3 lookAt  = vec3(0.0);
    vec3 forward = normalize(lookAt - ro);

    // Compute camera basis
    vec3 worldUp = vec3(0,1,0);
    vec3 right   = normalize(cross(forward, worldUp));
    vec3 up      = cross(right, forward);
    vec3 rd      = normalize(mat3(right, up, forward) * vec3(uv, 1.0));

    // background gradient
    vec3 bg        = mix(vec3(0.3), vec3(0.01), clamp(1.0 - (uv.y*0.5+0.5), 0.0, 1.0));
    vec4 finalColor= vec4(bg,1.0);

    // bounding cube intersection
    vec2 tCube = cubeIntersection(ro, rd);
    if(tCube.x < tCube.y && tCube.y > 0.0)
    {
        float t    = max(tCube.x,0.0);
        float tEnd = tCube.y;

        vec4 acc = vec4(0.0);
        for(int i=0; i<MAX_STEPS && t<tEnd; i++)
        {
            if(acc.a>0.99) break;
            vec3 pos = ro + rd*t;

            float d1, d2, d3;
            int cellId;
            getCellInfo(pos, d1, cellId, d2, d3);

            float boundaryDist   = abs(d2 - d1);
            float tripleThreshold= 0.003;
            float delta12        = abs(d2 - d1);
            float delta13        = abs(d3 - d1);
            bool isTriple        = (delta12 < tripleThreshold && delta13 < tripleThreshold);

            // step size
            float stepSize = 0.01;
            if(isTriple) stepSize = 0.003;

            if(isTriple)
            {
                float edgeStrength=1.0 - smoothstep(0.0, tripleThreshold, max(delta12, delta13));
                float glowFalloff =80.0;
                float glowStrength=0.3;
                float distFromEdge= max(delta12, delta13);
                float glowFactor  = glowStrength * exp(-glowFalloff*distFromEdge);

                float combined = edgeStrength + glowFactor;
                vec3 edgeCol   = vec3(0.0);

                float alpha=(1.0-acc.a)*0.4;
                acc.rgb += edgeCol * combined * alpha * 1.5;
                acc.a   += alpha;
            }
            else
            {
                float faceThreshold=0.003;
                if(boundaryDist<faceThreshold)
                {
                    float faceInt=1.0 - smoothstep(0.0, faceThreshold, boundaryDist);
                    vec3 faceCol = vec3(0.9);
                    float alpha  = (1.0 - acc.a)*0.02*faceInt;

                    acc.rgb += faceCol*alpha;
                    acc.a   += alpha;
                }
            }

            //-----------------------------------------
            // WIRE #1 => YELLOW, WIRE #2 => WHITE
            //-----------------------------------------
            if(cellId >= 0 && cellId < TOTAL_WIRE_POINTS)
            {
                float tintStrength = 0.1;
                float alpha = (1.0 - acc.a)*tintStrength;

                if(cellId < N)
                {
                    // wire #1 => YELLOW
                    vec3 wireColor = vec3(1.0,0.97,0.0);
                    acc.rgb += wireColor*alpha;
                    acc.a   += alpha;
                }
                else
                {
                    // wire #2 => WHITE
                    vec3 wireColor = vec3(1.0);
                    acc.rgb += wireColor*alpha;
                    acc.a   += alpha;
                }
            }

            t += stepSize;
        }

        // blend over background
        if(acc.a>0.0)
        {
            finalColor = mix(finalColor, vec4(acc.rgb/acc.a, acc.a), acc.a);
        }
    }

    fragColor = finalColor;
}

////////////////////////////////////////////////////////////
//                 BUFFER A
////////////////////////////////////////////////////////////
#define MAX_SITES 200

//----------------------------------------
// 2 wires, each with N points => total 2N
//----------------------------------------
#define N 32
#define TOTAL_WIRE_POINTS (2*N)

//----------------------------------------
// Geometric constants
#define RADIUS       0.35
#define R_OFFSET     0.08
#define TWISTS       2.0

// Large front–back motion along z
#define PENDULUM_AMP   0.8
#define PENDULUM_SPEED 1.0

//----------------------------------------
#define MAX_STEPS_MARCH 100
#define MIN_DIST 0.002
#define MAX_DIST 50.0
#define EPSILON 0.002
#define CUBE_SIZE 1.0
#define MAX_SITES_PER_CELL 50

const vec3 CUBE_SIZE_VEC = vec3(CUBE_SIZE);
const vec3 NEG_CUBE_SIZE_VEC = vec3(-CUBE_SIZE);

struct Site {
    vec3 pos;
    float weight;
};

// --------------------------------------------------
// Simple hash
vec3 hash33(vec3 p3) {
    p3 = fract(p3 * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yxz + 19.19);
    return -1.0 + 2.0 * fract((p3.xxy + p3.yzz) * p3.zyx);
}

// --------------------------------------------------
// Convert position in [-1..1] to 5x5x5 cell coords
ivec3 calculateGridPos(vec3 pos) {
    return clamp(
        ivec3((pos / CUBE_SIZE + 1.0) * 0.5 * 5.0),
        ivec3(0), ivec3(4)
    );
}

// --------------------------------------------------
// Rotation around Z-axis (like a steering wheel)
mat3 rotationZ(float a) {
    float c = cos(a), s = sin(a);
    return mat3(
        c, -s, 0.0,
        s,  c, 0.0,
        0.0,0.0,1.0
    );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 ipx = ivec2(fragCoord);

    if (ipx.y < 1 && ipx.x < MAX_SITES)
    {
        int i = ipx.x;

        //-------------------------------------------------
        // (A) TWO "WIRES" (double helix) around an invisible ring
        //-------------------------------------------------
        if (i < TOTAL_WIRE_POINTS)
        {
            // wire #1 => i in [0..N-1]
            // wire #2 => i in [N..2N-1]
            bool isWire1 = (i < N);
            int idx      = isWire1 ? i : (i - N);

            // Param t in [0..2π)
            float t = 6.283185307 * float(idx) / float(N);

            // The base circle in the x–y plane:
            float cx = RADIUS * cos(t);
            float cy = RADIUS * sin(t);

            // radial normal & binormal
            vec3 Ndir = vec3(-cos(t), -sin(t), 0.0);  // inward
            vec3 Bdir = vec3(0.0, 0.0, 1.0);          // "up" out of plane

            // wire #1 => phi=TWISTS*t
            // wire #2 => phi=TWISTS*t + π
            float phi = isWire1 ? (TWISTS*t) : (TWISTS*t + 3.14159265);

            float offN = R_OFFSET * cos(phi);
            float offB = R_OFFSET * sin(phi);

            // Local ringPos in x–y plane
            vec3 ringPos = vec3(cx, cy, 0.0)
                         + offN*Ndir
                         + offB*Bdir;

            //-----------------------------------------
            // "Pendulum" value => how far forward/back
            //-----------------------------------------
            float swingVal = sin(iTime * PENDULUM_SPEED);

            // 1) Rotate around Z (like a steering wheel)
            //    Multiply by 2 for faster rotation
            float spinAngle = 2.0 * swingVal;
            ringPos = rotationZ(spinAngle) * ringPos;

            // 2) Now push/pull along Z to go front/back
            ringPos.z += PENDULUM_AMP * swingVal;

            // clamp
            ringPos = clamp(ringPos, vec3(-0.9), vec3(0.9));

            // store final
            fragColor = vec4(ringPos * CUBE_SIZE, 1.0);
            return;
        }
        else
        {
            //-------------------------------------------------
            // (B) CLOUD / SWIRLING SITES
            //-------------------------------------------------
            float fi = float(i);

            // random base pos in [-0.9..0.9]
            vec3 basePos = hash33(vec3(fi * 0.0573, fi * 0.0731, fi * 0.0917)) * 0.9;

            // gentle swirl
            float swirlAmp = 0.10;
            float timeScale= iTime * 0.25;
            float swirlX   = basePos.x + swirlAmp * sin(timeScale + fi * 0.3);
            float swirlY   = basePos.y + swirlAmp * sin(timeScale * 0.7 + fi * 0.5);
            float swirlZ   = basePos.z + 0.08     * sin(timeScale * 0.4 + fi * 1.1);

            vec3 pos = clamp(vec3(swirlX, swirlY, swirlZ), vec3(-0.9), vec3(0.9)) * CUBE_SIZE;
            fragColor = vec4(pos, 1.0);
            return;
        }
    }

    //-----------------------------------------------
    // 2) Build the 5x5x5 grid data
    //-----------------------------------------------
    int grid_size = 125; // 5*5*5
    if (ipx.y > 0 && ipx.y <= grid_size)
    {
        int grid_index    = ipx.y - 1;
        int sites_per_row = MAX_SITES_PER_CELL + 1;

        // (a) first pixel => # sites in cell
        if (ipx.x < 1)
        {
            int grid_count = 0;
            ivec3 grid_cell_pos = ivec3(
                grid_index % 5,
                (grid_index / 5) % 5,
                grid_index / 25
            );
            for (int i = 0; i < MAX_SITES; i++)
            {
                vec3 site_pos = texelFetch(iChannel0, ivec2(i,0),0).xyz;
                ivec3 cell    = calculateGridPos(site_pos);
                if (cell == grid_cell_pos) grid_count++;
            }
            fragColor = vec4(float(grid_count),0,0,0);
        }
        // (b) next pixels => store indices
        else if (ipx.x < sites_per_row)
        {
            int grid_count = 0;
            ivec3 grid_cell_pos = ivec3(
                grid_index % 5,
                (grid_index / 5) % 5,
                grid_index / 25
            );
            int output_site_index = -1;

            for (int i = 0; i < MAX_SITES; i++)
            {
                vec3 site_pos = texelFetch(iChannel0, ivec2(i,0),0).xyz;
                ivec3 cell    = calculateGridPos(site_pos);
                if (cell == grid_cell_pos)
                {
                    if (grid_count == ipx.x - 1) {
                        output_site_index = i;
                    }
                    grid_count++;
                }
            }
            fragColor = vec4(float(output_site_index) + 0.5,0,0,0);
        }
        else
        {
            fragColor = vec4(0.0);
        }
        return;
    }

    // 3) pass-through
    fragColor = texelFetch(iChannel0, ipx, 0);
}   /////
